public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    String hexChars = "0123456789abcdef";
    while (i < bb.limit()) {
        byte b = bb.get(i++);
        if (b == 0x00) {
            continue;
        }
        int high = ((b & 0xF0) >>> 4) & 0xF, low = (b & 0x0F);
        sb.append(hexChars.charAt(high)).append(hexChars.charAt(low));
    }
    return i;
}
