private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int j = 0;
    while (j < 4) {
        int b = bb.get();
        sb.append((char) (b & 0xFF));
        b = (b << 8);
        b |= bb.get();
        j++;
    }
    return i + (4 * j);
}
