private static URL[] getJarsInDir(File dir) {
    File[] files = dir.listFiles((d, name) -> name.endsWith(".jar") || name.endsWith(".JAR") || name.endsWith(".war") || name.endsWith(".ear") || name.endsWith(".zip"));
    if (files != null) {
        URL[] urls = new URL[files.length];
        for (int i = 0; i < files.length; i++) {
            urls[i] = files[i].toURI().toURL();
        }
        return urls;
    }
    return null;
}

