public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    V vid = graph.getVertexIDs().iterator().next();
    IsomorphicGraphMapping edgeMapping = new IsomorphicGraphMapping();
    for (Edge<E> edge : graph.getEdges()) {
        Vertex<V> v1 = graph.get(edge.getSource());
        Vertex<V> v2 = graph.get(edge.getDestination());
        if (v1.getName().equals(vid) && v2.getName().equals(vid)) {
            edgeMapping.addEdgeMapping(edge.getSource().getLabel(), edge.getDestination().getLabel());
        }
    }
    return edgeMapping;
}
