    int a = 2;
    int b = 8;

    Integer[] vertexIds = new Integer[a + b];
    for (int i = 0; i < a; i++) {
        vertexIds[i] = a + i;
    }
    for (int i = a; i < a + b; i++) {
        vertexIds[i] = i;
    }

    disjointSetDisjointSets ds = new disjointSetDisjointSets(vertexIds.length);

    GraphEdge connectingEdge = new GraphEdge(0, 0, 0);

    for (int i = 0 ; i < b-1; i ++ ) {
        connectingEdge.setSource(vertexIds[i]);
        connectingEdge.setTarget(vertexIds[i+1]);
        connectingEdge.setWeight(1);
        target.addEdge(connectingEdge);
        connectingEdge = new GraphEdge(0, 0, 0);
    }

    ds.union(a-1, a);

    connectingEdge.setSource(vertexIds[a]);
    connectingEdge.setTarget(vertexIds[a+b-1]);
    connectingEdge.setWeight(0);
    target.addEdge(connectingEdge);
}
