public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    if ( str == null ) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int size = 0;
    int i = index;
    while ( i < index + len && i < str.length() ) {
        if ( (str.charAt(i) & 0x80) == 0 ) { // 1-byte character
            size += 1;
        } else if ( (str.charAt(i) & 0xE0) == 0xC0 ) { // 2-byte character
            size += 2;
            i++; // Skip the second byte
        } else if ( (str.charAt(i) & 0xF0) == 0xE0 ) { // 3-byte character
            size += 3;
            i += 2; // Skip the second and third bytes
        } else if ( (str.charAt(i) & 0xF8) == 0xF0 ) { // 4-byte character
            size += 4;
            i += 3; // Skip the second, third, and fourth bytes
        }
        i++; // Increment the index
    }

    return size;
}
```

