public static int computeUTF8Size(CharSequence str, int index, int len) {
    byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int b = bytes[i];
        if (b <= 127) {
            size++;
        } else if (b <= 191 && b >= 128) {
            size += 2;
        } else if (b <= 223 && b >= 192) {
            size += 3;
        } else if (b <= 239 && b >= 224) {
            size += 4;
        }
    }
    return size;
}
