public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            putByte((byte) 0);
        }
        return this;
    }

    if (byteArrayValue.length + byteOffset > length) {
        enlarge(byteArrayValue.length + byteOffset - length);
    }

    byte[] tempData = new byte[length + byteLength];
    byte[] data = this.data;

    System.arraycopy(data, 0, tempData, 0, Math.min(byteLength, data.length - byteOffset));
    System.arraycopy(byteArrayValue, byteOffset, tempData, byteLength, Math.min(byteArrayValue.length, byteLength - byteOffset));

    this.data = tempData;
    this.length += byteLength;
    return this;
}
