public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        return Collections.emptyList();
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (decode) {
        path = URLDecoder.decode(path, "UTF-8");
    }

    int start = 0;
    while (start < path.length()) {
        int end = path.indexOf('/', start);
        if (end == -1) {
            pathSegments.add(new PathSegmentImpl(path, start, path.length()));
            break;
        }
        pathSegments.add(new PathSegmentImpl(path, start, end - start));
        start = end + 1;
    }

    return pathSegments;
}
