public long readRawVarint64() throws IOException {
    long value = 0;
    boolean seen1, seen2, seen3;
    byte b;
    seen1 = seen2 = seen3 = false;

    while ((b = read(1)) != 0) {
        if (seen1 && seen2 && seen3) {
            throw new IOException("Varint is too large");
        }
        value <<= 7;
        if (b > 127) {
            value |= b & 0x7f;
            seen1 = true;
        } else if (b == 127) {
            seen1 = true;
        } else {
            seen1 = seen2 = seen3 = true;
        }
        if (!seen1) {
            value |= b & 0x7f;
        }
        if (!seen2) {
            value |= b & 0x7f;
        }
        if (!seen3) {
            value |= b & 0x7f;
        }
    }

    if (value > Integer.MAX_VALUE || value < Integer.MIN_VALUE) {
        throw new IOException("Varint is too large");
    }

    return value;
}
