import java.awt.geom.Rectangle2D;
import java.awt.geom.Point2D;
import org.javatuples.Pair;
import com.google.common.collect.Lists;

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box must not be null");
    }

    double width = box.getWidth();
    Point2D.Double midpoint = new Point2D.Double(box.getX() + width / 2, box.getY());
    Area upperArea = new Area(box);
    upperArea.subtract(new Area(new Rectangle2D.Double(box.getX(), box.getY(), midpoint.getX() - box.getX(), box.getHeight())));

    Area lowerArea = new Area(box);
    lowerArea.subtract(new Area(new Rectangle2D.Double(midpoint.getX() - box.getWidth() / 2, box.getY(), box.getWidth() / 2 + box.getX(), box.getHeight())));

    return Pair.with(upperArea.toShape(), lowerArea.toShape());
}
```

