    buffer.clear();
    try {
        int bytesRead = in.read(buffer.array(), buffer.position(), buffer.remaining());
        if (bytesRead < 0) {
            throw new EOFException("End of input stream reached");
        }
        buffer.position(bytesRead);
    } finally {
        in.close();
    }
}
