            content.put(key, buildContentArray(value.getAsJsonArray()));
        } else if (value.isBoolean()) {
            content.put(key, value.getAsBoolean());
        } else if (value.isNumber()) {
            content.put(key, value.getAsNumber());
        } else if (value.isString()) {
            content.put(key, value.getAsString());
