public static String unescapeJava(String str) throws Exception {
    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            i++; // Skip the backslash
            if (i >= len) {
                throw new IllegalArgumentException("Unmatched backslash at the end.");
            }
            char nextCh = str.charAt(i);
            switch (nextCh) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case '\b':
                    result.append('\b');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case 'l':
                    result.append('\l');
                    break;
                default:
                    // Encode escaped characters as though they're Java source code literals
                    if (nextCh > 31 && nextCh < 127) {
                        result.append('\\');
                        result.append(nextCh);
                    } else if (nextCh == 10) {
                        result.append('\n');
                    } else if (nextCh == 13) {
                        result.append('\r');
                    } else if (nextCh == 8) {
                        result.append('\b');
                    } else if (nextCh == 9) {
                        result.append('\t');
                    } else if (nextCh == 127) {
                        result.append('\\');
                        result.append(127);
                    } else {
                        // Encode other characters (like Unicode) as hex
                        // This is extremely simplified and does not handle all cases.
                        result.append("\\u");
                        result.append(String.format("%04X", nextCh));
                    }
            }
        } else {
            result.append(ch);
        }
    }
    return result.toString();
}
