private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node loc;
    outer:
    do {
        switch (dir) {
            case -1: // Traversing backwards
                loc = start;
                while (loc != null && !predicate.test(loc)) {
                    loc = loc.getPreviousSibling();
                }
                break;
            case 1: // Traversing forwards
                loc = start;
                while (loc != null && !predicate.test(loc)) {
                    loc = loc.getNextSibling();
                }
                break;
        }
        if (loc == null) {
            loc = stop;
            break outer;
        }
    } while (true);
    return new OuterFaceCirculator.Builder()
            .setNode(loc)
            .setDirection(dir)
            .build();
}
