    byte[] arr2 = (byte[]) aObj2;

    int minLength = Math.min(arr1.length, arr2.length);

    for (int i = 0; i < minLength; i++) {
        if (arr1[i] != arr2[i]) {
            return Integer.compare(arr1[i], arr2[i]);
        }
    }

    return Integer.compare(arr1.length, arr2.length);
