public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        V v = graph.getEdgeSource(edge);
        V w = graph.getEdgeTarget(edge);
        // Ensure the vertices are added in the order they appear
        if (!vertices.contains(v) || !vertices.contains(w)) {
            vertices.add(v);
            vertices.add(w);
        }
    }
    GraphPath<V,E> path = new GraphPath<>(graph, vertices, null);
    return path;
}
