import java.util.*;

public class EdgeSetToTour {
    protected static GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        List<Vertex<V>> path = new ArrayList<>();
        Vertex<V> current = graph.getVertices().iterator().next();
        path.add(current);

        Set<E> visited = new HashSet<>(tour);
        while (visited.size() < graph.getVertices().size()) {
            Set<E> outgoingEdges = current.getOutgoingEdges();
            if (outgoingEdges.stream().noneMatch(visited::contains)) {
                E nextEdge = outgoingEdges.iterator().next();
                Vertex<V> nextVertex = graph.getEdgeTarget(nextEdge);
                path.add(nextVertex);
                visited.add(nextEdge);
                current = nextVertex;
            } else {
                while (!visited.contains(current.getOutgoingEdges().stream().iterator().next())) {
                    path.remove(path.size() - 1);
                    current = path.get(path.size() - 1);
                }
            }
        }

        GraphPath<V, E> graphPath = new GraphPath<>();
        graphPath.setNodes(path);
        graphPath.setEdges(path.stream().map(Vertex::getEdge).collect(Collectors.toList()));
        return graphPath;
    }
}
