```java
private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean inQuoted = false;
    int i = 0, n = input.length();
    while (i < n) {
        char ch = input.charAt(i);
        if (ch == '"') {
            inQuoted = !inQuoted;
        } else if (inQuoted) {
            sb.append(ch);
        } else if (ch == '\\') {
            i++;
            if (i == n) {
                break;
            }
            char esc = input.charAt(i);
            if ("0123456789ABCDEFabcdef".indexOf(esc) != -1) {
                sb.append((char) (10 * Character.digit(esc, 16) + Character.digit(input.charAt(i + 1), 16)));
                i++;
            } else if (esc == 'n') {
                sb.append("\n");
            } else if (esc == 'r') {
                sb.append("\r");
            } else if (esc == 't') {
                sb.append("\t");
            } else if (esc == '\\') {
                sb.append("\\");
            } else if (esc == '?') {
                sb.append("?");
            } else {
                sb.append('\\');
            }
        } else if (ch == '.') {
            if (i > 0 && input.charAt(i - 1) != '.' && (i + 1 < n && input.charAt(i + 1) != '.')) {
                sb.append('U');
            }
        }
        i++;
    }
    return sb.toString();
}
