private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketByLabel == null || labels == null || bucketsByLabel.isEmpty() || labels.isEmpty() || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    // Clear all vertices from the bucket with label minLabel
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket != null) {
        minLabelBucket.clear();
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling accordingly
    int newLabel = 0;
    for (int i = 1; i < bucketsByLabel.size(); i++) {
        bucketsByLabel.get(i).clear();
        bucketsByLabel.set(i, new HashSet<>());
        labels.set(i, newLabel++);
    }
}
