    if (node == null) return false;
    ListNodeImpl<E> prev = null;
    ListNodeImpl<E> curr = first;
    while (curr != null && curr != node) {
        prev = curr;
        curr = curr.next;
    }
    if (curr != null) {
        if (prev == null) {
            first = curr.next;
        } else {
            prev.next = curr.next;
        }
        node.next = null;
        return true;
    }
    return false;
}
