import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class SuffixSumCalculator {
    private List<Integer> bounds;

    public SuffixSumCalculator(List<Integer> bounds) {
        this.bounds = bounds;
    }

    public Pair<List<Integer>, Long> computeSuffixSum() {
        List<Integer> suffixSumList = new ArrayList<>();
        long totalSum = 0;

        // Calculate the suffix sum list
        for (int i = bounds.size() - 1; i >= 0; i--) {
            suffixSumList.add(totalSum);
            totalSum += bounds.get(i);
        }

        // Reverse the list to get the correct order
        Collections.reverse(suffixSumList);

        return Pair.of(suffixSumList, totalSum);
    }
}

