import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class SuffixSumCalculator {
    private List<Integer> bounds;

    public SuffixSumCalculator(List<Integer> bounds) {
        this.bounds = new CopyOnWriteArrayList<>(bounds);
    }

    public Pair<List<Integer>, Long> computeSuffixSum() {
        long total = 0;
        List<Integer> suffixSum = new ArrayList<>();

        for (int i = bounds.size() - 1; i >= 0; i--) {
            total += bounds.get(i);
            suffixSum.add(total);
        }

        Collections.reverse(suffixSum);

        return new Pair<>(suffixSum, total);
    }
}
