private void moveAllListNodes(DoublyLinkedList<E> list) {
    try {
        final ListNode<E> headNode = list.getFirst();
        if (headNode != null) {
            // Move node to the head of the new list
            ListNode<E> currentNode = headNode;
            while (currentNode != null) {
                ListNode<E> nextNode = currentNode.getNext();
                currentNode.setPrevious(null);
                currentNode.setNext(null);
                addListNode(currentNode);
                currentNode = nextNode;
            }

            // Clear the old list
            clear();
        }
    } catch (Exception e) {
        // Handle any exceptions that occur during the move operation
        e.printStackTrace();
        throw new RuntimeException("Failed to move all list nodes", e);
    }
}
