private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null || prefix == null) {
        return str == prefix;
    }
    if (str.length() < prefix.length()) {
        return false;
    }
    int index = 0;
    while (index < prefix.length() && str.charAt(index) == prefix.charAt(index)) {
        index++;
    }
    return ignoreCase
            ? str.substring(index).equalsIgnoreCase(prefix.substring(index))
            : str.substring(index).equals(prefix.substring(index));
}
```

