    private int indegree(E vertex) {
        // Implementation of getting the indegree of a vertex
        // This can involve iterating over all edges and counting the number of vertices v that form an edge with vertex
        // Example implementation:
        int indegree = 0;
        Collection<Pair<Integer, Integer>> neighbors = getNeighbors(vertex);
        for (Pair<Integer, Integer> neighbor : neighbors) {
            indegree++;
        }
        return indegree;
    }

