public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty() || relativePath.trim().isEmpty()) {
        return path;
    }

    String[] splitRelativePath = relativePath.split(File.separator);
    if (splitRelativePath.length == 0) {
        return path;
    }

    String fullPath = path;
    for (String segment : splitRelativePath) {
        fullPath = fullPath.endsWith(File.separator) ? fullPath + segment : fullPath + File.separator + segment;
    }

    return fullPath;
