protected void append(LoggingEvent event) {
    if (event == null) {
        log.error("Null event passed to append method");
        return;
    }

    ManagedReference<ClientSession> sessionRef = getServerContext().getSession(event.getClientHost(), event.getClientPort());

    if (sessionRef == null) {
        log.error("Session not found for client: " + event.getClientHost() + ":" + event.getClientPort());
        return;
    }

    Message message = getServerContext().getMessage(event.getMessage());
    String sessionName = getClientSessionInfo(sessionRef);

    try {
        byte[] data = message.getBytes();
        if (data != null) {
            sessionRef.getClient().sendText(new String(data));
        } else {
            log.error("Failed to send message: " + event.getMessage());
        }
    } catch (IOException e) {
        log.error("Error sending message to client", e);
    }

    logger.log(Level.INFO, "Handling log event for session: " + sessionName);
}
